1	import http from 'node:http';
2	import { SnapshotError, Workspace, normalizeTags } from './workspace.js';
3	import { sameDocument } from './history.js';
4	import { reconcileSnapshots } from './reconcile.js';
5	
6	const MAX_BODY_BYTES = 1024 * 1024;
7	// Bodies must be valid UTF-8: a fatal decode rejects lone continuation
8	// bytes, truncated or overlong multibyte sequences, surrogate code points,
9	// and out-of-range sequences instead of letting them surface as U+FFFD.
10	const fatalDecoder = new TextDecoder('utf-8', { fatal: true });
11	const ETAG_PATTERN = /^"[0-9a-f]{64}"$/u;
12	const ID_PATTERN = /^[a-z0-9][a-z0-9._-]*$/u;
13	const DOCUMENT_FIELDS = new Set(['id', 'title', 'body', 'tags']);
14	const BATCH_ACTIONS = new Set(['create', 'replace', 'delete', 'restore']);
15	const MAX_BATCH_OPERATIONS = 100;
16	const TAG_RULE_FIELDS = ['from', 'to'];
17	const MAX_TAG_RULES = 100;
18	
19	function compareCodePoints(a, b) {
20	  const left = Array.from(a, (char) => char.codePointAt(0));
21	  const right = Array.from(b, (char) => char.codePointAt(0));
22	  for (let i = 0; i < Math.min(left.length, right.length); i += 1) {
23	    if (left[i] !== right[i]) return left[i] - right[i];
24	  }
25	  return left.length - right.length;
26	}
27	
28	function sameTags(a, b) {
29	  return a.length === b.length && a.every((tag, i) => tag === b[i]);
30	}
31	
32	class HttpError extends Error {
33	  constructor(status, code, message, extra = {}) {
34	    super(message);
35	    this.name = 'HttpError';
36	    this.status = status;
37	    this.code = code;
38	    for (const [key, value] of Object.entries(extra)) this[key] = value;
39	  }
40	}
41	
42	function sendJson(res, status, payload, etag) {
43	  const headers = { 'content-type': 'application/json; charset=utf-8' };
44	  if (etag) headers.etag = etag;
45	  res.writeHead(status, headers);
46	  res.end(JSON.stringify(payload));
47	}
48	
49	// Reads and size-limits the raw request bytes. The byte count, not the
50	// decoded character count, is compared against the 1 MiB limit. A multibyte
51	// character split across transport chunks is reassembled by Buffer.concat, so
52	// the framing never affects later decoding.
53	async function readBody(req) {
54	  const declared = Number(req.headers['content-length']);
55	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) {
56	    req.resume();
57	    throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
58	  }
59	  const chunks = [];
60	  let size = 0;
61	  for await (const chunk of req) {
62	    size += chunk.length;
63	    if (size > MAX_BODY_BYTES) {
64	      throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
65	    }
66	    chunks.push(chunk);
67	  }
68	  return Buffer.concat(chunks);
69	}
70	
71	// Strictly decodes a request body as UTF-8: a lone continuation byte, a
72	// truncated or overlong multibyte sequence, an encoded surrogate code point,
73	// or bytes beyond the Unicode range are rejected instead of silently becoming
74	// U+FFFD in a stored document. (A U+FFFD that was itself encoded validly is
75	// ordinary text and decodes fine.) JSON escapes such as "\uD800" are untouched
76	// by this layer and keep their existing string semantics.
77	function decodeJsonBody(bytes) {
78	  try {
79	    return fatalDecoder.decode(bytes);
80	  } catch {
81	    throw new HttpError(400, 'INVALID_JSON', 'request body is not valid UTF-8');
82	  }
83	}
84	
85	function parseJson(text) {
86	  try {
87	    return JSON.parse(text);
88	  } catch {
89	    throw new HttpError(400, 'INVALID_JSON', 'request body is not valid JSON');
90	  }
91	}
92	
93	function validateDocument(data) {
94	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
95	    throw new HttpError(400, 'INVALID_DOCUMENT', 'document must be an object');
96	  }
97	  for (const key of Object.keys(data)) {
98	    if (!DOCUMENT_FIELDS.has(key)) {
99	      throw new HttpError(400, 'INVALID_DOCUMENT', `unknown document field: ${key}`);
100	    }
101	  }
102	  for (const key of ['id', 'title', 'body']) {
103	    if (typeof data[key] !== 'string' || !data[key].trim()) {
104	      throw new HttpError(400, 'INVALID_DOCUMENT', `${key} must be a non-empty string`);
105	    }
106	  }
107	  if (!ID_PATTERN.test(data.id)) {
108	    throw new HttpError(400, 'INVALID_DOCUMENT', 'id must be URL-safe lowercase text');
109	  }
110	  if (data.tags !== undefined && (!Array.isArray(data.tags) || data.tags.some((tag) => typeof tag !== 'string'))) {
111	    throw new HttpError(400, 'INVALID_DOCUMENT', 'tags must be an array of strings');
112	  }
113	  return { id: data.id, title: data.title, body: data.body, tags: data.tags ?? [] };
114	}
115	
116	// Validates the batch envelope and every operation, returning normalized
117	// `{ operations, dryRun }`. Structural problems (bad envelope shape, unknown
118	// type, wrong fields, missing id, non-string id) are INVALID_BATCH; document
119	// content problems follow the single-document rules (INVALID_DOCUMENT), and a
120	// revision that is not a positive integer is INVALID_REVISION.
121	function validateBatchRequest(data) {
122	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
123	    throw new HttpError(400, 'INVALID_BATCH', 'batch body must be an object');
124	  }
125	  for (const key of Object.keys(data)) {
126	    if (key !== 'operations' && key !== 'dryRun') {
127	      throw new HttpError(400, 'INVALID_BATCH', `unknown batch field: ${key}`);
128	    }
129	  }
130	  if (!Array.isArray(data.operations)) {
131	    throw new HttpError(400, 'INVALID_BATCH', 'operations must be an array');
132	  }
133	  if (data.operations.length < 1 || data.operations.length > MAX_BATCH_OPERATIONS) {
134	    throw new HttpError(400, 'INVALID_BATCH', `operations must contain 1 to ${MAX_BATCH_OPERATIONS} items`);
135	  }
136	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
137	  if (typeof dryRun !== 'boolean') {
138	    throw new HttpError(400, 'INVALID_BATCH', 'dryRun must be a boolean');
139	  }
140	
141	  const operations = data.operations.map((op, index) => {
142	    if (!op || typeof op !== 'object' || Array.isArray(op)) {
143	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] must be an object`);
144	    }
145	    const type = op.type;
146	    if (typeof type !== 'string' || !BATCH_ACTIONS.has(type)) {
147	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has an unknown type`);
148	    }
149	    const expectedKeys = type === 'create' || type === 'replace'
150	      ? ['type', 'document']
151	      : type === 'delete'
152	        ? ['type', 'id']
153	        : ['type', 'id', 'revision'];
154	    const keys = Object.keys(op);
155	    if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) {
156	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has invalid fields for ${type}`);
157	    }
158	
159	    if (type === 'create' || type === 'replace') {
160	      if (!op.document || typeof op.document !== 'object' || Array.isArray(op.document)) {
161	        throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] document must be an object`);
162	      }
163	      return { type, document: validateDocument(op.document) };
164	    }
165	
166	    if (typeof op.id !== 'string') {
167	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] id must be a string`);
168	    }
169	
170	    if (type === 'delete') {
171	      return { type, id: op.id };
172	    }
173	
174	    // restore: the envelope is structurally valid; the revision value itself
175	    // follows the single-document restore rules.
176	    if (op.revision === undefined) {
177	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] restore requires a revision`);
178	    }
179	    if (!Number.isInteger(op.revision) || op.revision < 1) {
180	      throw new HttpError(400, 'INVALID_REVISION', `operations[${index}] revision must be a positive integer`);
181	    }
182	    return { type, id: op.id, revision: op.revision };
183	  });
184	
185	  // Every operation targets a distinct document id.
186	  const seen = new Set();
187	  for (const op of operations) {
188	    const id = op.type === 'create' || op.type === 'replace' ? op.document.id : op.id;
189	    if (seen.has(id)) {
190	      throw new HttpError(400, 'INVALID_BATCH', `duplicate target id in batch: ${id}`);
191	    }
192	    seen.add(id);
193	  }
194	
195	  return { operations, dryRun };
196	}
197	
198	// Counts current tag usage across the live documents. Deleted documents are
199	// absent from the workspace and therefore never counted; history is ignored.
200	function tagStats(workspace) {
201	  const counts = new Map();
202	  for (const document of workspace.list()) {
203	    for (const tag of document.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
204	  }
205	  return [...counts.entries()]
206	    .map(([tag, count]) => ({ tag, count }))
207	    .sort((a, b) => compareCodePoints(a.tag, b.tag));
208	}
209	
210	// Validates the rewrite envelope and every rule, returning normalized
211	// `{ rules, dryRun }` as `[{ from, to }]` pairs of trimmed, lowercased names
212	// (`to` stays `null` for removals). Structural problems, empty normalized
213	// names, duplicate sources, and out-of-range rule counts are INVALID_TAG_RULES.
214	function validateTagRules(data) {
215	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
216	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rewrite body must be an object');
217	  }
218	  for (const key of Object.keys(data)) {
219	    if (key !== 'rules' && key !== 'dryRun') {
220	      throw new HttpError(400, 'INVALID_TAG_RULES', `unknown rewrite field: ${key}`);
221	    }
222	  }
223	  if (!Array.isArray(data.rules)) {
224	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rules must be an array');
225	  }
226	  if (data.rules.length < 1 || data.rules.length > MAX_TAG_RULES) {
227	    throw new HttpError(400, 'INVALID_TAG_RULES', `rules must contain 1 to ${MAX_TAG_RULES} items`);
228	  }
229	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
230	  if (typeof dryRun !== 'boolean') {
231	    throw new HttpError(400, 'INVALID_TAG_RULES', 'dryRun must be a boolean');
232	  }
233	
234	  const rules = data.rules.map((rule, index) => {
235	    if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
236	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must be an object`);
237	    }
238	    const keys = Object.keys(rule);
239	    if (keys.length !== TAG_RULE_FIELDS.length || !TAG_RULE_FIELDS.every((key) => keys.includes(key))) {
240	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must contain exactly from and to`);
241	    }
242	    if (typeof rule.from !== 'string') {
243	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must be a string`);
244	    }
245	    if (typeof rule.to !== 'string' && rule.to !== null) {
246	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must be a string or null`);
247	    }
248	    const from = rule.from.trim().toLowerCase();
249	    const to = rule.to === null ? null : rule.to.trim().toLowerCase();
250	    if (!from) {
251	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must not be blank`);
252	    }
253	    if (to !== null && !to) {
254	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must not be blank`);
255	    }
256	    return { from, to };
257	  });
258	
259	  const seen = new Set();
260	  for (const { from } of rules) {
261	    if (seen.has(from)) {
262	      throw new HttpError(400, 'INVALID_TAG_RULES', `duplicate source tag after normalization: ${from}`);
263	    }
264	    seen.add(from);
265	  }
266	
267	  return { rules, dryRun };
268	}
269	
270	// Validates the reconcile envelope `{ base, incoming, dryRun? }`, where base
271	// and incoming are version-1 snapshot objects (strings are not accepted at
272	// this layer; malformed JSON is rejected earlier by the shared body parser).
273	// Snapshot contents themselves are validated by normalizeSnapshot via the
274	// reconcile core, which reports INVALID_SNAPSHOT.
275	function validateReconcileRequest(data) {
276	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
277	    throw new HttpError(400, 'INVALID_OPTIONS', 'reconcile body must be an object');
278	  }
279	  for (const key of Object.keys(data)) {
280	    if (key !== 'base' && key !== 'incoming' && key !== 'dryRun') {
281	      throw new HttpError(400, 'INVALID_OPTIONS', `unknown reconcile field: ${key}`);
282	    }
283	  }
284	  if (!data.base || typeof data.base !== 'object' || Array.isArray(data.base)) {
285	    throw new HttpError(400, 'INVALID_OPTIONS', 'base must be a snapshot object');
286	  }
287	  if (!data.incoming || typeof data.incoming !== 'object' || Array.isArray(data.incoming)) {
288	    throw new HttpError(400, 'INVALID_OPTIONS', 'incoming must be a snapshot object');
289	  }
290	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
291	  if (typeof dryRun !== 'boolean') {
292	    throw new HttpError(400, 'INVALID_OPTIONS', 'dryRun must be a boolean');
293	  }
294	  return { base: data.base, incoming: data.incoming, dryRun };
295	}
296	
297	// A document server holds one Workspace and, when a history store is supplied,
298	// a per-document revision ledger. Every committed change is persisted through
299	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
300	// failed save leaves memory, queries, history, and the original files
301	// untouched. Everything here is synchronous, so a commit is atomic with
302	// respect to other requests.
303	export function createDocumentServer({ workspace, save, history = null }) {
304	  let current = workspace;
305	  let ledger = history;
306	
307	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
308	
309	  function requireIfMatch(req) {
310	    const value = req.headers['if-match'];
311	    if (value === undefined) {
312	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
313	    }
314	    if (!ETAG_PATTERN.test(value)) {
315	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
316	    }
317	    if (value !== currentEtag()) {
318	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
319	    }
320	  }
321	
322	  function assertTitleFree(candidate, title) {
323	    const trimmed = title.trim();
324	    for (const existing of candidate.list()) {
325	      if (existing.title === trimmed) {
326	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
327	      }
328	    }
329	  }
330	
331	  // Builds the next state on a candidate workspace and lets `mutate` append to
332	  // the next ledger. The callback returns false to signal a content-preserving
333	  // write (normalized content unchanged): the request still succeeds, but no
334	  // revision is appended and nothing is persisted.
335	  function commit(mutate) {
336	    const candidate = new Workspace();
337	    for (const document of current.list()) candidate.add(document);
338	    const nextLedger = ledger ? ledger.clone() : null;
339	    const changed = mutate(candidate, nextLedger);
340	    if (changed === false) {
341	      return current.exportJSON();
342	    }
343	    const snapshot = candidate.exportJSON();
344	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
345	    current = candidate;
346	    ledger = nextLedger;
347	    return snapshot;
348	  }
349	
350	  // Applies every operation in one atomic step. Existence and restore-version
351	  // checks all run against the pre-commit state, so a batch is rejected whole
352	  // if any operation would fail. Title conflicts are checked against the final
353	  // projected set, making swaps and release-then-reuse independent of
354	  // operation order. Each actually-changed document appends one record; a
355	  // normalized-identical replace or restore appends nothing. Returns
356	  // `{ snapshot, changed }` without persisting when `dryRun` is true or the
357	  // batch is content-preserving.
358	  function commitBatch(operations, dryRun) {
359	    // Pre-commit state checks.
360	    for (const op of operations) {
361	      if (op.type === 'create') {
362	        if (current.get(op.document.id)) {
363	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
364	        }
365	      } else if (op.type === 'replace') {
366	        if (!current.get(op.document.id)) {
367	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
368	        }
369	      } else if (op.type === 'delete') {
370	        if (!current.get(op.id)) {
371	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
372	        }
373	      } else if (op.type === 'restore') {
374	        if (!ledger) {
375	          throw new HttpError(404, 'NOT_FOUND', 'history is not enabled');
376	        }
377	        const chain = ledger.entries(op.id);
378	        if (!chain) {
379	          throw new HttpError(404, 'NOT_FOUND', `document never existed: ${op.id}`);
380	        }
381	        const target = ledger.entry(op.id, op.revision);
382	        if (!target) {
383	          throw new HttpError(404, 'NOT_FOUND', `unknown revision ${op.revision} for document ${op.id}`);
384	        }
385	        if (target.action === 'delete') {
386	          throw new HttpError(400, 'INVALID_REVISION', `revision ${op.revision} of document ${op.id} is a delete and cannot be restored`);
387	        }
388	      }
389	    }
390	
391	    const candidate = new Workspace();
392	    for (const document of current.list()) candidate.add(document);
393	    const nextLedger = ledger ? ledger.clone() : null;
394	
395	    let changed = false;
396	    for (const op of operations) {
397	      if (op.type === 'create') {
398	        candidate.add(op.document);
399	        if (nextLedger) nextLedger.record(op.document.id, 'create', candidate.get(op.document.id));
400	        changed = true;
401	      } else if (op.type === 'replace') {
402	        const before = current.get(op.document.id);
403	        candidate.remove(op.document.id);
404	        candidate.add(op.document);
405	        const stored = candidate.get(op.document.id);
406	        if (!sameDocument(before, stored)) {
407	          if (nextLedger) nextLedger.record(op.document.id, 'replace', stored);
408	          changed = true;
409	        }
410	      } else if (op.type === 'delete') {
411	        candidate.remove(op.id);
412	        if (nextLedger) nextLedger.record(op.id, 'delete', null);
413	        changed = true;
414	      } else if (op.type === 'restore') {
415	        const before = current.get(op.id);
416	        const target = ledger.entry(op.id, op.revision);
417	        candidate.remove(op.id);
418	        candidate.add(target.document);
419	        const stored = candidate.get(op.id);
420	        if (!before || !sameDocument(before, stored)) {
421	          nextLedger.record(op.id, 'restore', stored);
422	          changed = true;
423	        }
424	      }
425	    }
426	
427	    // Title conflicts are checked against the final projected set, so
428	    // operation order cannot make a swap or release-then-reuse fail.
429	    const titles = new Set();
430	    for (const document of candidate.list()) {
431	      if (titles.has(document.title)) {
432	        throw new HttpError(409, 'CONFLICT', `title conflict in batch: ${document.title}`);
433	      }
434	      titles.add(document.title);
435	    }
436	
437	    if (dryRun) {
438	      return { snapshot: candidate.exportJSON(), changed };
439	    }
440	    if (!changed) {
441	      return { snapshot: current.exportJSON(), changed: false };
442	    }
443	
444	    const snapshot = candidate.exportJSON();
445	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
446	    current = candidate;
447	    ledger = nextLedger;
448	    return { snapshot, changed: true };
449	  }
450	
451	  async function createDocument(req, res) {
452	    const bytes = await readBody(req);
453	    requireIfMatch(req);
454	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
455	    const snapshot = commit((candidate, nextLedger) => {
456	      if (candidate.get(document.id)) {
457	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
458	      }
459	      assertTitleFree(candidate, document.title);
460	      candidate.add(document);
461	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
462	    });
463	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
464	  }
465	
466	  async function replaceDocument(req, res, id) {
467	    const bytes = await readBody(req);
468	    requireIfMatch(req);
469	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
470	    if (document.id !== id) {
471	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
472	    }
473	    if (!current.get(id)) {
474	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
475	    }
476	    const before = current.get(id);
477	    const snapshot = commit((candidate, nextLedger) => {
478	      candidate.remove(id);
479	      assertTitleFree(candidate, document.title);
480	      candidate.add(document);
481	      const stored = candidate.get(id);
482	      // A replace whose normalized content is identical succeeds without
483	      // consuming a revision or touching the files.
484	      if (sameDocument(before, stored)) return false;
485	      if (nextLedger) nextLedger.record(id, 'replace', stored);
486	      return true;
487	    });
488	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
489	  }
490	
491	  function deleteDocument(req, res, id) {
492	    requireIfMatch(req);
493	    if (!current.get(id)) {
494	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
495	    }
496	    const snapshot = commit((candidate, nextLedger) => {
497	      candidate.remove(id);
498	      if (nextLedger) nextLedger.record(id, 'delete', null);
499	    });
500	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
501	  }
502	
503	  function historyDocument(req, res, id) {
504	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for GET /documents/${id}/history`);
505	    const entries = ledger.entries(id);
506	    if (!entries) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
507	    sendJson(res, 200, entries, currentEtag());
508	  }
509	
510	  async function restoreDocument(req, res, id) {
511	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for POST /documents/${id}/restore`);
512	    const bytes = await readBody(req);
513	    requireIfMatch(req);
514	    // Bad UTF-8 is an INVALID_JSON transport-level failure; only once the
515	    // bytes decode do the restore-specific parse/shape rules apply, which
516	    // keep reporting INVALID_REVISION as before.
517	    const text = decodeJsonBody(bytes);
518	    let data;
519	    try {
520	      data = JSON.parse(text);
521	    } catch {
522	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
523	    }
