563	  // Applies the tag rules to the pre-rewrite tag set of every document. Each
564	  // original tag is looked up once, so a rule result is never itself rewritten
565	  // (a→b then b→c moves the original `a` straight to `b`) and swaps resolve
566	  // because `to` names are carried independently of the source keys. Returns
567	  // `{ snapshot, changedIds }` without persisting when `dryRun` is true or the
568	  // rewrite leaves the tag set unchanged.
569	  function commitTagRewrite(rules, dryRun) {
570	    const mapping = new Map(rules.map((rule) => [rule.from, rule.to]));
