577	    for (const from of mapping.keys()) {
578	      if (!used.has(from)) throw new HttpError(404, 'TAG_NOT_FOUND', `tag not in use: ${from}`);
579	    }
580	
581	    const candidate = new Workspace();
582	    for (const document of current.list()) candidate.add(document);
583	    const nextLedger = ledger ? ledger.clone() : null;
584	
585	    const changedIds = [];
586	    for (const document of current.list()) {
587	      if (!document.tags.some((tag) => mapping.has(tag))) continue;
588	      // A null target removes the tag; mapped results are emitted as-is
589	      // without a second lookup, so new names are never chained further.
590	      const nextTags = normalizeTags(
591	        document.tags.flatMap((tag) => {
592	          if (!mapping.has(tag)) return [tag];
593	          const target = mapping.get(tag);
