608	    }
609	    if (changedIds.length === 0) {
610	      // Tag set unchanged: report the current snapshot and no file/version work.
611	      return { snapshot: current.exportJSON(), changedIds: [] };
612	    }
613	
614	    const snapshot = candidate.exportJSON();
615	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
616	    current = candidate;
617	    ledger = nextLedger;
618	    return { snapshot, changedIds };
619	  }
620	
621	  async function rewriteTags(req, res) {
622	    const bytes = await readBody(req);
623	    requireIfMatch(req);
624	    const { rules, dryRun } = validateTagRules(parseJson(decodeJsonBody(bytes)));
625	    const { snapshot, changedIds } = commitTagRewrite(rules, dryRun);
626	    sendJson(res, 200, { snapshot, changedIds }, `"${snapshot.checksum}"`);
627	  }
628	
629	  // Merges an offline-edited incoming snapshot back against its base, keeping
630	  // non-conflicting online edits. The merge is computed against the current
631	  // live state; field/add/delete/title conflicts reject the whole request.
632	  // Each actually-changed document appends one ledger record (create for new
633	  // or reappearing ids, replace for edits, delete for removals), continuing
634	  // that id's revision sequence. Returns `{ snapshot, changedIds }` without
635	  // persisting when `dryRun` is true or the merge leaves the content equal to
636	  // the current state.
637	  function commitReconcile(base, incoming, dryRun) {
638	    const currentSnapshot = current.exportJSON();
639	    const result = reconcileSnapshots(currentSnapshot, base, incoming);
640	    if (result.conflicts.length > 0) {
641	      throw new HttpError(409, 'RECONCILE_CONFLICT', 'reconcile conflicts detected', {
