22	    ? (a, b) => sameTags(a, b)
23	    : (a, b) => a === b;
24	  const currentChanged = !same(currentValue, baseValue);
25	  const incomingChanged = !same(incomingValue, baseValue);
26	  if (currentChanged && incomingChanged && !same(currentValue, incomingValue)) {
