33	// Three-way merge of an offline-edited `incoming` snapshot against the edit
34	// `base` snapshot, preserving non-conflicting online changes in `current`.
35	// Bodies compare (and are kept) as whole strings; tags compare as one
36	// normalized group. Returns `{ snapshot, changedIds, conflicts }`, where
37	// `changedIds` lists the documents that differ from `current` after the merge.
38	export function reconcileSnapshots(currentData, baseData, incomingData) {
