297	// Builds an independent, mutable copy of a workspace. Every committed
298	// projection is prepared on such a copy and only swapped in after its
299	// snapshot has been saved, so a failed save or a rejected business check
300	// never mutates the live state.
301	function cloneWorkspace(source) {
302	  const candidate = new Workspace();
303	  for (const document of source.list()) candidate.add(document);
304	  return candidate;
305	}
306	
307	// A document server holds one Workspace and, when a history store is supplied,
308	// a per-document revision ledger. Every committed change is persisted through
309	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
310	// failed save leaves memory, queries, history, and the original files
311	// untouched. Everything here is synchronous, so a commit is atomic with
312	// respect to other requests.
313	export function createDocumentServer({ workspace, save, history = null }) {
314	  let current = workspace;
315	  let ledger = history;
316	
317	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
318	
319	  function requireIfMatch(req) {
320	    const value = req.headers['if-match'];
321	    if (value === undefined) {
322	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
323	    }
324	    if (!ETAG_PATTERN.test(value)) {
325	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
326	    }
327	    if (value !== currentEtag()) {
328	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
329	    }
330	  }
331	
332	  function assertTitleFree(candidate, title) {
333	    const trimmed = title.trim();
334	    for (const existing of candidate.list()) {
335	      if (existing.title === trimmed) {
336	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
337	      }
338	    }
339	  }
340	
341	  // Single commit rule shared by every write route. `project` runs against a
342	  // fresh workspace copy (and a cloned ledger when history is enabled) and
343	  // returns `{ changed, extra }`; it may throw to reject the request before
344	  // any save. When `changed` is false the normalized content is identical:
345	  // the request still succeeds on the current snapshot, but no file is
346	  // written, no revision appended, and the ETag is unchanged. When `dryRun`
347	  // is true the projected snapshot is returned without touching memory,
348	  // history, or files. Otherwise the result snapshot and its ledger export
349	  // are saved first; the in-memory state is swapped in only once the save
350	  // succeeds, so every subsequent read (document, search, tags, links,
351	  // history) observes the full commit and a failed save leaves the request
352	  // fully uncommitted.
353	  function commitChange(project, { dryRun = false } = {}) {
354	    const candidate = cloneWorkspace(current);
355	    const nextLedger = ledger ? ledger.clone() : null;
356	    const { changed = true, extra } = project(candidate, nextLedger) ?? {};
357	    if (!changed) {
358	      return { snapshot: current.exportJSON(), committed: false, extra };
359	    }
360	    const snapshot = candidate.exportJSON();
361	    if (dryRun) {
362	      return { snapshot, committed: false, extra };
363	    }
364	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
365	    current = candidate;
366	    ledger = nextLedger;
367	    return { snapshot, committed: true, extra };
368	  }
369	
370	  // Applies every operation in one atomic step. Existence and restore-version
371	  // checks all run against the pre-commit state, so a batch is rejected whole
372	  // if any operation would fail. Title conflicts are checked against the final
373	  // projected set, making swaps and release-then-reuse independent of
374	  // operation order. Each actually-changed document appends one record; a
375	  // normalized-identical replace or restore appends nothing. The shared
376	  // commit rule skips persistence when the batch is content-preserving or a
377	  // preview.
378	  function commitBatch(operations, dryRun) {
379	    // Pre-commit state checks.
380	    for (const op of operations) {
381	      if (op.type === 'create') {
382	        if (current.get(op.document.id)) {
383	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
384	        }
385	      } else if (op.type === 'replace') {
386	        if (!current.get(op.document.id)) {
387	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
388	        }
389	      } else if (op.type === 'delete') {
390	        if (!current.get(op.id)) {
391	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
392	        }
